#include "cuda_utils.cuh"
#include <vector>
#include <iostream>
__global__ void transform(const float* x,float* y,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)y[i]=x[i]*x[i]+2*x[i];}
int main(){const int N=1<<22,streams=4,chunk=(N+streams-1)/streams;size_t bytes=N*sizeof(float);float *hx,*hy;CUDA_CHECK(cudaMallocHost(&hx,bytes));CUDA_CHECK(cudaMallocHost(&hy,bytes));for(int i=0;i<N;i++)hx[i]=i*.0001f;std::vector<cudaStream_t>s(streams);std::vector<float*>dx(streams),dy(streams);for(int k=0;k<streams;k++){CUDA_CHECK(cudaStreamCreate(&s[k]));CUDA_CHECK(cudaMalloc(&dx[k],chunk*4));CUDA_CHECK(cudaMalloc(&dy[k],chunk*4));}for(int k=0;k<streams;k++){int off=k*chunk,n=std::min(chunk,N-off);if(n<=0)continue;CUDA_CHECK(cudaMemcpyAsync(dx[k],hx+off,n*4,cudaMemcpyHostToDevice,s[k]));transform<<<(n+255)/256,256,0,s[k]>>>(dx[k],dy[k],n);check_kernel("transform");CUDA_CHECK(cudaMemcpyAsync(hy+off,dy[k],n*4,cudaMemcpyDeviceToHost,s[k]));}CUDA_CHECK(cudaDeviceSynchronize());for(int i=0;i<N;i++)if(!nearly_equal(hy[i],hx[i]*hx[i]+2*hx[i],1e-3f,1e-5f))return 1;for(int k=0;k<streams;k++){CUDA_CHECK(cudaFree(dx[k]));CUDA_CHECK(cudaFree(dy[k]));CUDA_CHECK(cudaStreamDestroy(s[k]));}CUDA_CHECK(cudaFreeHost(hx));CUDA_CHECK(cudaFreeHost(hy));std::cout<<"PASS\n";}
